#include "loader/Zip.hpp"
#include <chrono>
#include <ctime>
#include <cinttypes>
#include <cstdio>
#include <vector>
using Clock=std::chrono::steady_clock;
int main(int argc,char** argv) {
    if(argc!=2)return 2;
    double metadata=0,decode=0,cpu=0;
    uint64_t hash=14695981039346656037ull;size_t bytes=0,files=0,entries=0;
    constexpr int iterations=8;
    for(int i=0;i<iterations;++i) {
        const auto cpu0=std::clock();auto t=Clock::now();
        Hydrogen::Loader::ZipReader z(argv[1]);const auto afterMetadata=Clock::now();
        std::vector<std::vector<uint8_t>> all;
        for(const auto& e:z.entries())if(!e.isDirectory())all.push_back(z.read(e));
        const auto afterDecode=Clock::now();cpu+=double(std::clock()-cpu0)/CLOCKS_PER_SEC;
        metadata+=std::chrono::duration<double>(afterMetadata-t).count();
        decode+=std::chrono::duration<double>(afterDecode-afterMetadata).count();
        entries=z.entries().size();files=all.size();
        // Content verification is outside measured parse/decode time.
        for(const auto& a:all){bytes+=a.size();for(auto b:a){hash^=b;hash*=1099511628211ull;}}
    }
    std::printf("{\"iterations\":%d,\"entriesPerIteration\":%zu,\"filesPerIteration\":%zu,\"bytesAcrossIterations\":%zu,\"contentFnv1a64\":\"%016" PRIx64 "\",\"metadataWallSeconds\":%.9f,\"readWallSeconds\":%.9f,\"parseReadCpuSeconds\":%.9f}\n",iterations,entries,files,bytes,hash,metadata,decode,cpu);
}
